Q: Monaco Editor (Diff Viewer) - How do I only show the changes in a diff without the rest of the file contents A: <p>I know this is 3 years old, and you have probably forgotten, but I had the same problem and came up with a solution / hack that works for me. I also have the changes only and do not wish to display the whole file, since in my context that file can be in a different state than what I am displaying and I do not wish to store a copy of the original.</p>
<p>Anyway, my hack was to fill all the lines that were unchanged with empty lines before displaying the diff and making the editor hide the unchanged lines (in this case hiding the empty lines) with <code>hideUnchangedRegions</code> option. Maybe can even be hacked more to hide the controls to show the empty lines, but I can't be bothered, it works well enough for me.</p>
<p>From the back end parse a unified diff and I receive the changes as a list with this type:</p>
<pre class="lang-js prettyprint-override"><code>type Line {
    original_line_no: Number, // the position of the line in the original file
    new_line_no: Number, // the position of the line in the result after changes,
    operation: &quot;added&quot; | &quot;unchanged&quot; | &quot;removed&quot;, // The action taken for this line, &quot;unchanged&quot; is for context lines.
    content: String, // The value of the line
    terminator: String, // The line ending of the line
}

type Change {
    file: String, // the file that was changed
    original_start: Number, // the start line of the original, from hunk header
    original_count: Number, // the number of lines in the original, from hunk header
    new_start: Number, // the start line of the change, from hunk header
    new_count: Number, // the number of lines in the change, from hunk header
    lines: Line[], // the changed lines
    original: String, // the original string before the change, including context lines
    new: String, // The resulting string, including context lines.
}

type FileChange {
    file: String, // the name of the file
    hunks: Change[], // all the changes for this file.
    original: String, // The original concatenated and merged with a file with empty lines until the last change.
    modified: String, // The changes concatenated and merged with a file with empty lines until the last change.
    diffModel: Object {
        original: monaco.editor.ITextModel,
        modified: monaco.editor.ITextModel,
    },
}
</code></pre>
<p>Here is a snippet:</p>
<pre class="lang-js prettyprint-override"><code>/**
 * Group the given changes into a a file change array.
 *
 * @param  {Change[]} changes
 * @return {FileChange[]}
 */
function groupChangesByFile(changes)
{
    const groups = {};

    for(let change of changes) {
        if (typeof groups[change.file] == 'undefined') {
            groups[change.file] = {
                file: change.file,
                hunks: [],
            };
        }

        groups[change.file].hunks.push(change);
    }

    return groups;
}

/**
 * Add padding of missing lines and monaco diff models per file changes.
 *
 * @param  {FileChange[]}  changes The changes grouped by file.
 * @return {FileChange[]}
 */
function createMonacoModels(changes)
{
    for (const [file, change] of Object.entries(changes)) {
        let original = '', modified = '';

        for (const hunk of change.hunks) {
            // add padding until the start of hunk
            const currentOriginalLines = countLines(original);
            const currentModifiedLines = countLines(modified);

            // add padding to show correct lines in editor because we don't have the full file
            if (hunk.original_start &gt; currentOriginalLines) {
                original = original + '\n'.repeat(hunk.original_start - currentModifiedLines);
            }

            // add padding to show correct lines in editor because we don't have the full file
            if (hunk.new_start &gt; currentModifiedLines) {
                modified = modified + '\n'.repeat(hunk.new_start - currentModifiedLines);
            }

            original = original + hunk.original;
            modified = modified + hunk.new;
        }

        // TODO: Detect language from change.
        change.diffModel = {
            original: monaco.editor.createModel(original, 'text/plain'),
            modified: monaco.editor.createModel(modified, 'text/plain'),
        };
        change.original = original;
        change.modified = modified;
    }

    return changes;
}

function countLines(str)
{
    return (str.match(/\n/g) || '').length + 1;
}

function initDiff()
{
    let changes = fetch(...);
    changes = groupChangesByFile(changes);
    changes = createMonacoModels(changes);

    const editor = window.monacoEditor(
        document.getElementById('patch-diff'),
        {
            glyphMargin: false,
            folding: false,
            lineNumbersMinChars: 4,
            scrollBeyondLastLine: false,
            language: 'diff',
            minimap: {
                enabled: true,
            },
            readOnly: true,
            enableSplitViewResizing: false,
            // this is the important setting, that hides the unchanged (empty lines)
            hideUnchangedRegions: {
                enabled: true,
                minimumLineCount: 1,
                contextLineCount: 2,
            },
            experimentalWhitespaceRendering: 'svg',
            renderOverviewRuler: false,
            // value: '',
        },
        'diff'
    );
}

// my entry point is when monaco has initialised.
window.addEventListener('monaco-ready', initDiff);
</code></pre>
