Q: I got Initialization error in Cucumber with maven and selenium A: <p>Your pom file is absolutely fine.</p>
<p>Here you are using Scenario Outline if you are using Scenario outline there should be Examples annotation in the feature file. Anyways your test scenario can be achieved without using scenario outline</p>
<p>Update feature file and java file with below code:</p>
<p>Myapplication.feature:
Feature: Test test smoke scenario</p>
<pre><code>  Scenario: Test  login with valid credentials
     Given open fireFox and start application
     When I click on Login
     When I enter valid &quot;username&quot; and valid &quot;password&quot;
     Then I click on Loginbutton
     Then User should be able to login successfully
</code></pre>
<p>Smoke.java:</p>
<pre><code>import java.util.concurrent.TimeUnit;

import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.firefox.FirefoxDriver;
import cucumber.api.java.en.Given;
import cucumber.api.java.en.Then;
import cucumber.api.java.en.When;

public class Smoke {
   WebDriver driver;
@Given(&quot;^open fireFox and start application$&quot;)
public void open_fireFox_and_start_application() throws Throwable {
    driver=new FirefoxDriver();
    driver.manage().timeouts().implicitlyWait(20, TimeUnit.SECONDS);
    driver.manage().window().maximize();
    driver.get(&quot;https://testweb.com&quot;);

}

 @When(&quot;^I click on Login$&quot;)
    public void I_click_on_Login() throws Throwable {
        driver.findElement(By.xpath(&quot;//a[contains(.,'Login')]&quot;)).click();
    }

@When(&quot;^I enter valid \&quot;([^\&quot;]*)\&quot; and valid \&quot;([^\&quot;]*)\&quot;$&quot;)
public void i_enter_valid_and_valid(String arg1, String arg2) throws   Throwable {
    driver.findElement(By.id(&quot;Username&quot;)).sendKeys(arg1);
    driver.findElement(By.id(&quot;Password&quot;)).sendKeys(arg2);
}


@Then(&quot;^I click on Loginbutton$&quot;)
public void Click_on_Login() throws Throwable {
    driver.findElement(By.id(&quot;loginUser&quot;)).click();

}
@Then(&quot;^User should be able to login successfully$&quot;)
public void User_should_be_able_to_login_successfully() throws Throwable {


}
}
</code></pre>
